CustomField.formula:
if( 
Final_Comm_Month_Calculated__c < Date(2000, 1, 1) || IsBlank(Final_Comm_Month_Calculated__c ), "Not Yet Billing", 

Text(Year(Final_Comm_Month_Calculated__c ))&"-"&
if(Month(Final_Comm_Month_Calculated__c )<10, "0"&Text(Month(Final_Comm_Month_Calculated__c )), Text(Month(Final_Comm_Month_Calculated__c )))&
"-01"
)
